-- ── Contrôle d'arrivée ────────────────────────────────────────────────────
do $$
declare v_compte int;
begin
  select count(*) into v_compte
    from public.food_catalog
   where source = 'ciqual'
     and source_version = '2025';
  if v_compte <> 3330 then
    raise exception 'IMPORT CIQUAL INCOMPLET : % lignes en base, 3330 attendues', v_compte;
  end if;
end $$;
